{
  "name": "安捷伦 VSpin 离心机",
  "name_en": "Agilent VSpin Centrifuge",
  "manufacturer": "Agilent",
  "description": "用于实验室样品离心处理的自动化离心机，可进行转子位置控制、开关门、门锁与桶锁控制，并按设定的相对离心力或转速执行离心程序。",
  "description_en": "An automated laboratory centrifuge for sample separation, supporting rotor positioning, door open/close control, door and bucket locking, and spin programs based on target relative centrifugal force or RPM.",
  "tag_hints": [
    "centrifugation",
    "rotor position control",
    "door lock interlock",
    "bucket lock control",
    "RPM monitoring",
    "g-force to RPM conversion",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-close_door",
      "description": "关闭离心机门。",
      "description_en": "Close the centrifuge door."
    },
    {
      "action_name": "auto-configure_and_initialize",
      "description": "配置并初始化离心机。",
      "description_en": "Configure and initialize the centrifuge."
    },
    {
      "action_name": "auto-go_to_bucket1",
      "description": "将转子移动到桶位 1。",
      "description_en": "Move the rotor to bucket position 1."
    },
    {
      "action_name": "auto-go_to_bucket2",
      "description": "将转子移动到桶位 2。",
      "description_en": "Move the rotor to bucket position 2."
    },
    {
      "action_name": "auto-go_to_position",
      "description": "将转子移动到指定位置。",
      "description_en": "Move the rotor to a specified position."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化离心机。",
      "description_en": "Initialize the centrifuge."
    },
    {
      "action_name": "auto-lock_bucket",
      "description": "锁定样品桶。",
      "description_en": "Lock the bucket."
    },
    {
      "action_name": "auto-lock_door",
      "description": "锁定离心机门。",
      "description_en": "Lock the centrifuge door."
    },
    {
      "action_name": "auto-open_door",
      "description": "打开离心机门。",
      "description_en": "Open the centrifuge door."
    },
    {
      "action_name": "auto-set_bucket_1_position_to_current",
      "description": "将当前位置设为桶位 1 并保存校准。",
      "description_en": "Set the current position as bucket 1 and save the calibration."
    },
    {
      "action_name": "auto-set_configuration_data",
      "description": "设置设备配置数据。",
      "description_en": "Set the device configuration data."
    },
    {
      "action_name": "auto-setup",
      "description": "执行离心机设置与校准加载。",
      "description_en": "Perform centrifuge setup and load calibration."
    },
    {
      "action_name": "auto-spin",
      "description": "按设定离心力、时长、加速度和减速度执行离心。",
      "description_en": "Run a spin cycle with the specified g-force, duration, acceleration, and deceleration."
    },
    {
      "action_name": "auto-stop",
      "description": "停止离心机运行。",
      "description_en": "Stop the centrifuge."
    },
    {
      "action_name": "auto-unlock_bucket",
      "description": "解锁样品桶。",
      "description_en": "Unlock the bucket."
    },
    {
      "action_name": "auto-unlock_door",
      "description": "解锁离心机门。",
      "description_en": "Unlock the centrifuge door."
    },
    {
      "action_name": "auto-send_command",
      "description": "发送底层设备命令。",
      "description_en": "Send a low-level device command."
    },
    {
      "action_name": "auto-serialize",
      "description": "序列化设备配置或状态。",
      "description_en": "Serialize the device configuration or state."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态。",
      "description_en": "Get device status."
    },
    {
      "action_name": "auto-park",
      "description": "执行停放流程。",
      "description_en": "Perform the park procedure."
    },
    {
      "action_name": "auto-load",
      "description": "执行装载流程。",
      "description_en": "Perform the load procedure."
    },
    {
      "action_name": "auto-unload",
      "description": "执行卸载流程。",
      "description_en": "Perform the unload procedure."
    },
    {
      "action_name": "auto-bucket_1_remainder",
      "description": "获取桶位 1 的校准余量。",
      "description_en": "Get the bucket 1 calibration remainder."
    },
    {
      "action_name": "auto-get_bucket_1_position",
      "description": "获取桶位 1 的位置。",
      "description_en": "Get the bucket 1 position."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取当前转子位置。",
      "description_en": "Get the current rotor position."
    },
    {
      "action_name": "auto-get_tachometer",
      "description": "获取当前转速。",
      "description_en": "Get the current speed."
    },
    {
      "action_name": "auto-get_home_position",
      "description": "获取原点位置。",
      "description_en": "Get the home position."
    },
    {
      "action_name": "auto-get_bucket_locked",
      "description": "获取样品桶锁定状态。",
      "description_en": "Get the bucket lock state."
    },
    {
      "action_name": "auto-get_door_open",
      "description": "获取门打开状态。",
      "description_en": "Get the door open state."
    },
    {
      "action_name": "auto-get_door_locked",
      "description": "获取门锁定状态。",
      "description_en": "Get the door locked state."
    },
    {
      "action_name": "auto-g_to_rpm",
      "description": "将相对离心力换算为转速。",
      "description_en": "Convert relative centrifugal force to RPM."
    }
  ]
}

